// One-shot selective update. Runs only at the next authorized restart.
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {readFile,writeFile,mkdir,rename,copyFile,lstat,unlink} from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const root=path.dirname(fileURLToPath(import.meta.url)),release='3.5.0-live-player.1';
const data=path.resolve(root,process.env.DATA_DIR||'data'),backup=path.join(data,'restorepoints',release),stage=path.join(backup,'stage');
const sha=value=>createHash('sha256').update(value).digest('hex');
const plan=JSON.parse(gunzipSync(Buffer.from('','base64')));
const permitted=new Set(['package.json','package-lock.json','server.mjs','room.mjs','ip-policy.mjs','sources.mjs','page-extractor.mjs','public/app.js','public/index.html','public/style.css','public/beta.js','public/pro.js']);
const state=JSON.parse(await readFile(path.join(data,'state.json'),'utf8'));
if(!['owner','viewer','playlistAlias'].every(k=>typeof state[k]==='string'&&state[k]))throw Error('Existing installation identity is required');
let applied=false;try{applied=JSON.parse(await readFile(path.join(backup,'applied.json'),'utf8')).release===release;}catch{}
if(!applied){
 await mkdir(stage,{recursive:true,mode:0o700});
 const entries=Object.entries(plan);if(entries.length!==permitted.size)throw Error('Unexpected release file count');
 for(const[name,item]of entries){
  if(!permitted.has(name)||sha(item.content)!==item.sha256)throw Error('Invalid release entry: '+name);
  const target=path.join(root,name),staged=path.join(stage,name);await mkdir(path.dirname(staged),{recursive:true,mode:0o700});
  for(const candidate of [path.dirname(target),target]){try{if((await lstat(candidate)).isSymbolicLink())throw Error('Refusing symlink: '+name);}catch(e){if(e.code!=='ENOENT')throw e;}}
  await writeFile(staged,item.content,{mode:0o600});
  if(/\.(?:mjs|js)$/.test(name))execFileSync(process.execPath,['--check',staged],{stdio:'pipe'});else if(name.endsWith('.json'))JSON.parse(item.content);
 }
 // Copy all old files and state before replacing any file. Backups remain private.
 const previous=[];
 for(const[name]of entries){const target=path.join(root,name),saved=path.join(backup,'files',name);await mkdir(path.dirname(saved),{recursive:true,mode:0o700});try{await copyFile(target,saved);previous.push({name,existed:true});}catch(e){if(e.code!=='ENOENT')throw e;previous.push({name,existed:false});}}
 await copyFile(path.join(data,'state.json'),path.join(backup,'state.json'));
 await writeFile(path.join(backup,'github-start.mjs'),plan['package.json'].launcherBefore,{mode:0o600});
 await writeFile(path.join(backup,'manifest.json'),JSON.stringify({release,previous},null,2),{mode:0o600});
 try{
  for(const[name]of entries)await rename(path.join(stage,name),path.join(root,name));
  for(const[name,item]of entries)if(sha(await readFile(path.join(root,name)))!==item.sha256)throw Error('Installed hash mismatch: '+name);
  const after=JSON.parse(await readFile(path.join(data,'state.json'),'utf8'));for(const key of ['owner','viewer','playlistAlias'])if(after[key]!==state[key])throw Error('Installation identity changed');
  await writeFile(path.join(backup,'applied.json'),JSON.stringify({release,at:new Date().toISOString(),files:entries.map(([name,item])=>({name,sha256:item.sha256}))}),{mode:0o600});
  console.log('[release-apply] '+release+'; 12 files verified; restorepoint saved; existing data preserved');
 }catch(error){
  for(const item of previous){const target=path.join(root,item.name);if(item.existed)await copyFile(path.join(backup,'files',item.name),target);else await unlink(target).catch(()=>{});}
  console.error('[release-apply] Rollback completed: '+error.message);throw error;
 }
}
